\section{Introduction}

\subsection{The phenomenon}
In Euclidean geometry, the angles of a triangle sum to $\pi$ and carry no information about size. In hyperbolic geometry the angle sum is strictly less than $\pi$, and the \emph{defect} $\pi-(\alpha+\beta+\gamma)$ is, up to the curvature normalisation, precisely the area. The immediate corollary --- that hyperbolic triangles have uniformly bounded area --- has no Euclidean counterpart and is one of the defining structural features of negative curvature. It underlies the finiteness of hyperbolic volumes of finite-type surfaces, the $\delta$-thinness of geodesic triangles that abstracts to Gromov hyperbolicity, and the ideal-tetrahedron decompositions used to compute hyperbolic structures on knot complements.

The extremal object is the \emph{ideal triangle}: three vertices on the circle at infinity, three geodesic sides meeting asymptotically at angle zero. It has infinite diameter and finite area $\pi/\kappa$.

\subsection{What this paper does}
Much exposition of this material treats the angle-defect formula as an input and reasons algebraically from it. That approach yields maximality and rigidity as trivial consequences of $\alpha,\beta,\gamma\ge 0$, but it never explains \emph{what a hyperbolic triangle is}, and in particular offers no independent verification that ideal triangles exist, that they all have the same area, or that the angle-zero configuration is unattainable in the interior of the plane.

We take the opposite route: fix a concrete Riemannian model, compute areas by integration, define interior angles from tangent vectors, and derive Gauss--Bonnet where we can. Section~\ref{sec:analytic} develops the analytic core; Section~\ref{sec:slicing} the slicing formula, the ideal triangle area, and ideal polygons; Section~\ref{sec:angles} the computation of interior angles and the derived Gauss--Bonnet identity; Section~\ref{sec:rigidity} maximality, rigidity and degeneration; Section~\ref{sec:mobius} the M\"obius isometry group and sharp three-transitivity; Section~\ref{sec:curvature} curvature comparison. Sections~\ref{sec:algorithms}--\ref{sec:discussion} give algorithms, applications, and open problems.

\subsection{Conventions}
Throughout, $\kappa>0$ denotes the \emph{curvature magnitude}, so the Gaussian curvature is $-\kappa$; the hyperbolic plane of curvature $-1$ corresponds to $\kappa=1$. All integrals are Lebesgue integrals; interval integrals $\int_{a}^{b}$ are oriented.

\section{The upper half-plane model}

\begin{definition}[Half-plane model]
The upper half-plane is $\HH = \{(x,y)\in\RR^{2}: y>0\}$, identified with $\{z\in\CC : \Imm z>0\}$, equipped with
\[
ds^{2} = \frac{dx^{2}+dy^{2}}{\kappa\,y^{2}},\qquad \kappa>0 .
\]
This metric has constant Gaussian curvature $-\kappa$ and area element $dA = dx\,dy/(\kappa y^{2})$.
\end{definition}

\begin{definition}[Boundary at infinity]
The ideal boundary is $\partial\HH = \RR\cup\{\infty\}$, a topological circle. Its points lie at infinite hyperbolic distance from every point of $\HH$ and are not points of the space.
\end{definition}

\begin{fact}[Geodesics]\label{fact:geo}
The complete geodesics of $\HH$ are precisely the vertical rays $\{x=c,\ y>0\}$, with ideal endpoints $c$ and $\infty$, and the Euclidean semicircles centred on the real axis, with ideal endpoints their two intersections with $\RR$.
\end{fact}

\begin{definition}[Chord height]
For $a<b$ and $x\in\RR$ put $h_{a,b}(x) = \sqrt{(x-a)(b-x)}$. On $(a,b)$ this is the height of the Euclidean semicircle with diameter $[a,b]$, that is, of the geodesic joining the boundary points $a$ and $b$.
\end{definition}

\begin{lemma}\label{lem:hpos}
If $a<x<b$ then $h_{a,b}(x)>0$.
\end{lemma}
\begin{proof}
$(x-a)(b-x)>0$, and the square root of a positive real is positive.
\end{proof}

\begin{definition}[Ideal triangle region]
For $a<b$, the ideal triangle with vertices $a$, $b$, $\infty$ is
\[
\Delta(a,b) = \{(x,y) : a<x<b,\ y>h_{a,b}(x)\}\subset\HH .
\]
Its boundary consists of the geodesic semicircle over $[a,b]$ and the two vertical geodesics $x=a$, $x=b$.
\end{definition}

\section{The analytic core}\label{sec:analytic}

\begin{definition}
For $a<b$ set $F_{a,b}(x) = \arcsin\bigl((2x-a-b)/(b-a)\bigr)$, a continuous function on $\RR$ mapping $[a,b]$ onto $[-\pi/2,\pi/2]$.
\end{definition}

\begin{theorem}[Derivative of the chordal antiderivative]\label{thm:deriv}
For all $x\in(a,b)$,
\[
F_{a,b}'(x) = \frac{1}{h_{a,b}(x)} = \frac{1}{\sqrt{(x-a)(b-x)}} .
\]
\end{theorem}
\begin{proof}
Write $u(x)=(2x-a-b)/(b-a)$, so $u'(x)=2/(b-a)$ and $|u(x)|<1$ on $(a,b)$. The chain rule gives $F_{a,b}'(x) = \bigl(2/(b-a)\bigr)\bigl(1-u(x)^{2}\bigr)^{-1/2}$. A direct computation yields the key identity
\[
1-u(x)^{2} = \frac{4(x-a)(b-x)}{(b-a)^{2}},
\]
so $\sqrt{1-u(x)^{2}} = 2\sqrt{(x-a)(b-x)}/(b-a)$, the positive root being correct as $b-a>0$ and $(x-a)(b-x)>0$. Substituting and cancelling $2/(b-a)$ gives the claim.
\end{proof}

\begin{lemma}[Endpoint values]\label{lem:endpoints}
For $a<b$: $F_{a,b}(a) = -\pi/2$ and $F_{a,b}(b)=\pi/2$.
\end{lemma}
\begin{proof}
$u(a)=-1$ and $u(b)=1$; then $\arcsin(\mp1)=\mp\pi/2$.
\end{proof}

\begin{theorem}[Improper integrability]\label{thm:integrable}
For any real $a,b$, the function $x\mapsto h_{a,b}(x)^{-1}$ is interval-integrable on $[a,b]$.
\end{theorem}
\begin{proof}[Proof sketch]
The density is nonnegative and, on the open interval, is the derivative of the continuous function $F_{a,b}$. A nonnegative derivative of a continuous function on a closed interval, differentiable on the interior, is integrable there: the increments of $F_{a,b}$ over compact subintervals bound the integrals uniformly, and monotone convergence supplies the limit. No dominating function is available near the endpoints; integrability comes from boundedness of the antiderivative instead.
\end{proof}

\begin{theorem}[Fundamental theorem across the singularities]\label{thm:ftc}
Let $a<b$ and $a\le u<v\le b$. Then
\[
\int_{u}^{v}\frac{dx}{h_{a,b}(x)} = F_{a,b}(v)-F_{a,b}(u) .
\]
\end{theorem}
\begin{proof}[Proof sketch]
On $(u,v)\subseteq(a,b)$ we have $F_{a,b}'=h_{a,b}^{-1}$ by Theorem~\ref{thm:deriv}, and the density is integrable on $[u,v]$ by Theorem~\ref{thm:integrable}. The endpoints may be singular, but $F_{a,b}$ is continuous, so its one-sided limits at $u^{+}$ and $v^{-}$ are $F_{a,b}(u)$ and $F_{a,b}(v)$. The version of the fundamental theorem valid for an interior derivative with integrable density and convergent boundary limits applies.
\end{proof}

\begin{theorem}[The ideal-triangle integral]\label{thm:pi}
For all $a<b$,
\[
\int_{a}^{b}\frac{dx}{\sqrt{(x-a)(b-x)}} = \pi .
\]
\end{theorem}
\begin{proof}
Take $u=a$, $v=b$ in Theorem~\ref{thm:ftc} and apply Lemma~\ref{lem:endpoints}: the value is $\pi/2-(-\pi/2)=\pi$.
\end{proof}

\begin{remark}
The value $\pi$ is \emph{independent of $a$ and $b$}; this single fact is the analytic reason that all ideal triangles are congruent. Geometrically the integral measures the angular sweep of the semicircular arch over $[a,b]$ seen from its centre --- a semicircle spans $\pi$ radians --- so the $\pi$ in the area of the largest triangle is the $\pi$ of a half-turn, arriving through $\arcsin$ rather than through any circle in the hyperbolic plane.
\end{remark}

\section{Areas by slicing}\label{sec:slicing}

\begin{theorem}[Fibre integral]\label{thm:fibre}
For $c>0$, $\displaystyle\int_{c}^{\infty} y^{-2}\,dy = 1/c$.
\end{theorem}
\begin{proof}
Apply $\int_{c}^{\infty}y^{s}\,dy = -c^{s+1}/(s+1)$, valid for $s<-1$, $c>0$, with $s=-2$.
\end{proof}

\begin{definition}[Sliced area]
For $\kappa\in\RR$, $a<b$, and $\mathrm{low}:\RR\to\RR$, set
\[
\mathcal{A}_{\kappa}(a,b;\mathrm{low}) = \int_{a}^{b}\!\left(\int_{\mathrm{low}(x)}^{\infty}\frac{dy}{\kappa y^{2}}\right)dx ,
\]
the hyperbolic area at curvature $-\kappa$ of $\{(x,y): a<x<b,\ y>\mathrm{low}(x)\}$.
\end{definition}

\begin{theorem}[Slicing]\label{thm:slice}
If $\mathrm{low}(x)>0$ for all $x\in(a,b)$, then
\[
\mathcal{A}_{\kappa}(a,b;\mathrm{low}) = \frac{1}{\kappa}\int_{a}^{b}\frac{dx}{\mathrm{low}(x)} .
\]
\end{theorem}
\begin{proof}[Proof sketch]
For each $x$ in the open interval --- hence almost every $x$ in $[a,b]$, the endpoints forming a null set --- the inner integral is $\kappa^{-1}\mathrm{low}(x)^{-1}$ by Theorem~\ref{thm:fibre}. Integrands agreeing almost everywhere have equal integrals, and the constant $\kappa^{-1}$ pulls out.
\end{proof}

\begin{theorem}[Ideal triangle area; Gauss--Bonnet derived]\label{thm:idealarea}
For $\kappa>0$ and $a<b$, the ideal triangle $\Delta(a,b)$ with vertices $a$, $b$, $\infty$ has hyperbolic area
\[
\mathcal{A}_{\kappa}\bigl(a,b;h_{a,b}\bigr) = \frac{\pi}{\kappa} .
\]
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:slice} with $\mathrm{low}=h_{a,b}$, positive on $(a,b)$ by Lemma~\ref{lem:hpos}, then Theorem~\ref{thm:pi}.
\end{proof}

\begin{corollary}[Congruence]
For any $a<b$ and $a'<b'$, the ideal triangles $\Delta(a,b)$ and $\Delta(a',b')$ have equal area: the invariant does not see the position of the finite ideal vertices.
\end{corollary}

\begin{definition}[Angle-defect invariant]
$\displaystyle \mathcal{G}_{\kappa}(\alpha,\beta,\gamma) = \frac{\pi-(\alpha+\beta+\gamma)}{\kappa}$.
\end{definition}

\begin{corollary}
$\mathcal{A}_{\kappa}(a,b;h_{a,b}) = \mathcal{G}_{\kappa}(0,0,0)$: the Riemannian area of the ideal triangle agrees with the Gauss--Bonnet prediction at all angles zero.
\end{corollary}

\subsection{Ideal polygons}

\begin{definition}
Let $m\ge1$ and $v_{0}<v_{1}<\dots<v_{m}$ in $\RR$. The ideal $n$-gon with $n=m+2$ vertices $v_{0},\dots,v_{m},\infty$ is cut by the vertical geodesics through $v_{1},\dots,v_{m-1}$ into chimneys over consecutive intervals; accordingly set
\[
\mathcal{P}_{\kappa}(m;v) = \sum_{i=0}^{m-1}\mathcal{A}_{\kappa}\bigl(v_{i},v_{i+1};h_{v_{i},v_{i+1}}\bigr).
\]
\end{definition}

\begin{theorem}[Area of an ideal polygon]\label{thm:polygon}
If $v_{i}<v_{i+1}$ for all $i<m$, then
\[
\mathcal{P}_{\kappa}(m;v) = \frac{m\pi}{\kappa} = \frac{(n-2)\pi}{\kappa},\qquad n=m+2 .
\]
\end{theorem}
\begin{proof}
Each of the $m$ summands equals $\pi/\kappa$ by Theorem~\ref{thm:idealarea}.
\end{proof}

\begin{theorem}[Triangulation invariance]
With $m,k\ge0$ and admissible vertex data $v$, $w$, $u$ for an ideal $(m+2)$-gon, an ideal $(k+2)$-gon and an ideal $(m+k+2)$-gon,
\[
\mathcal{P}_{\kappa}(m+k;u) = \mathcal{P}_{\kappa}(m;v)+\mathcal{P}_{\kappa}(k;w).
\]
\end{theorem}
\begin{proof}
All three sides evaluate by Theorem~\ref{thm:polygon} to $(m+k)\pi/\kappa$, $m\pi/\kappa$ and $k\pi/\kappa$.
\end{proof}

\begin{remark}
Gluing two ideal polygons along a common ideal edge adds their areas, and the value depends only on the number of vertices, not on the triangulation. This is the hyperbolic shadow of the Euclidean identity that the interior angles of an $n$-gon sum to $(n-2)\pi$: the same combinatorial coefficient, now measuring area.
\end{remark}

\section{Angles computed, not assumed}\label{sec:angles}

\begin{definition}
For nonzero $u,v\in\RR^{2}$,
\[
\angle(u,v) = \arccos\!\left(\frac{u_{1}v_{1}+u_{2}v_{2}}{\sqrt{u_{1}^{2}+u_{2}^{2}}\sqrt{v_{1}^{2}+v_{2}^{2}}}\right)\in[0,\pi].
\]
\end{definition}

\begin{theorem}[Conformal invariance]\label{thm:conf}
For every $c>0$ and all $u,v$: $\angle(cu,v)=\angle(u,v)=\angle(u,cv)$.
\end{theorem}
\begin{proof}
Under $u\mapsto cu$ the numerator scales by $c$ and $\sqrt{(cu_{1})^{2}+(cu_{2})^{2}} = c\sqrt{u_{1}^{2}+u_{2}^{2}}$ scales by $c$, so the quotient is unchanged; likewise on the right.
\end{proof}

\begin{corollary}[Hyperbolic angles are Euclidean angles]
The half-plane metric is the Euclidean metric multiplied pointwise by the positive scalar $1/(\kappa y^{2})$; by Theorem~\ref{thm:conf} the angle functional does not see this factor. Hyperbolic angles therefore coincide with Euclidean angles between the same tangent vectors, and are independent of $\kappa$.
\end{corollary}

\subsection{A one-parameter family with an ideal vertex}
Fix $0\le\varphi<\theta\le\pi$ and consider the region bounded below by the unit semicircle $|z|=1$ (a geodesic by Fact~\ref{fact:geo}) and on the sides by the vertical geodesics $x=\cos\theta$ and $x=\cos\varphi$; note $\cos\theta<\cos\varphi$ since $\cos$ is strictly decreasing on $[0,\pi]$. Its vertices are $P_{\theta}=(\cos\theta,\sin\theta)$, $P_{\varphi}=(\cos\varphi,\sin\varphi)$ and $\infty$. Relevant unit tangents: $T_{\mathrm{vert}}=(0,1)$; $T^{+}(\theta)=(\sin\theta,-\cos\theta)$ on the circle at $P_{\theta}$ in the direction of increasing $x$; $T^{-}(\varphi)=(-\sin\varphi,\cos\varphi)$ at $P_{\varphi}$ in the direction of decreasing $x$.

\begin{theorem}[Interior angles]\label{thm:angles}
For $0\le\theta\le\pi$ and $0\le\varphi\le\pi$,
\[
\angle\bigl(T_{\mathrm{vert}},T^{+}(\theta)\bigr)=\pi-\theta,\qquad
\angle\bigl(T_{\mathrm{vert}},T^{-}(\varphi)\bigr)=\varphi .
\]
\end{theorem}
\begin{proof}
Both circle tangents are unit vectors, so the angle functional reduces to $\arccos$ of the dot product. We get $\langle(0,1),(\sin\theta,-\cos\theta)\rangle=-\cos\theta$ and $\arccos(-\cos\theta)=\pi-\theta$ using $0\le\theta\le\pi$; likewise $\langle(0,1),(-\sin\varphi,\cos\varphi)\rangle=\cos\varphi$ and $\arccos(\cos\varphi)=\varphi$.
\end{proof}

At the third vertex $\infty$ the two sides are parallel vertical geodesics meeting asymptotically; the interior angle is $0$.

\begin{theorem}[Area with at least one ideal vertex]\label{thm:oneideal}
Let $0\le\varphi<\theta\le\pi$ and $\kappa\ne0$. The region above has hyperbolic area
\[
\mathcal{A}_{\kappa}\bigl(\cos\theta,\cos\varphi;h_{-1,1}\bigr) = \frac{\theta-\varphi}{\kappa}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Here $h_{-1,1}(x)=\sqrt{1-x^{2}}$ and $F_{-1,1}(x)=\arcsin x$, and $-1\le\cos\theta<\cos\varphi\le1$, so $[\cos\theta,\cos\varphi]$ is a subinterval of $[-1,1]$. Slicing (Theorem~\ref{thm:slice}) and the fundamental theorem on a subinterval (Theorem~\ref{thm:ftc}) give
$\mathcal{A}=\kappa^{-1}\bigl(\arcsin(\cos\varphi)-\arcsin(\cos\theta)\bigr)$.
For $0\le t\le\pi$ one has $\arcsin(\cos t)=\pi/2-t$, since $\cos t = \sin(\pi/2-t)$ and $\pi/2-t\in[-\pi/2,\pi/2]$. Substituting gives $(\theta-\varphi)/\kappa$.
\end{proof}

\begin{theorem}[Gauss--Bonnet, derived]\label{thm:gb}
With the hypotheses of Theorem~\ref{thm:oneideal} and $\alpha=\angle(T_{\mathrm{vert}},T^{+}(\theta))$, $\beta=\angle(T_{\mathrm{vert}},T^{-}(\varphi))$,
\[
\Area = \mathcal{G}_{\kappa}(\alpha,\beta,0) = \frac{\pi-(\alpha+\beta)}{\kappa}.
\]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:angles}, $\alpha=\pi-\theta$ and $\beta=\varphi$, so $\pi-(\alpha+\beta+0)=\theta-\varphi$; compare Theorem~\ref{thm:oneideal}.
\end{proof}

The angles were computed from the metric and the area from the area element; their agreement is a theorem, not a convention.

\begin{corollary}[One, two, three ideal vertices]
For $0<\varphi<\theta<\pi$ there is one ideal vertex, area $(\theta-\varphi)/\kappa$, angles $(\pi-\theta,\varphi,0)$. For $\varphi=0<\theta\le\pi$ there are two ideal vertices and area $\theta/\kappa = \mathcal{G}_{\kappa}(\pi-\theta,0,0)$. For $\varphi=0$, $\theta=\pi$ there are three, and the area is $\pi/\kappa$, recovering Theorem~\ref{thm:idealarea}.
\end{corollary}

\begin{theorem}[Strict positivity at finite vertices]\label{thm:strictpos}
If $0<\varphi<\theta<\pi$, so that both non-ideal vertices are genuine points of $\HH$, then $\alpha=\pi-\theta>0$ and $\beta=\varphi>0$.
\end{theorem}

\begin{corollary}[Strict subideality]
For $\kappa>0$ and $0<\varphi<\theta\le\pi$, $\Area=(\theta-\varphi)/\kappa<\pi/\kappa$.
\end{corollary}

Thus the maximal area $\pi/\kappa$ is not attained by any triangle with a finite vertex: the extremal object lies on the boundary of the space of triangles, not inside it.

\section{Maximality, rigidity, degeneration}\label{sec:rigidity}

\begin{definition}[Admissible angles]
A triple $(\alpha,\beta,\gamma)\in\RR^{3}$ is \emph{admissible} if $\alpha,\beta,\gamma\ge0$ and $\alpha+\beta+\gamma\le\pi$.
\end{definition}

\begin{theorem}[Maximality]
For $\kappa>0$ and admissible $(\alpha,\beta,\gamma)$: $\mathcal{G}_{\kappa}(\alpha,\beta,\gamma)\le\pi/\kappa$.
\end{theorem}
\begin{proof}
$\alpha+\beta+\gamma\ge0$, so the numerator is at most $\pi$; divide by $\kappa>0$.
\end{proof}

\begin{theorem}[Rigidity]
For $\kappa>0$ and admissible $(\alpha,\beta,\gamma)$:
$\mathcal{G}_{\kappa}(\alpha,\beta,\gamma)=\pi/\kappa$ if and only if $\alpha=\beta=\gamma=0$.
\end{theorem}
\begin{proof}
Equality forces $\alpha+\beta+\gamma=0$; with nonnegativity of each term, all vanish. Conversely $\mathcal{G}_{\kappa}(0,0,0)=\pi/\kappa$.
\end{proof}

\begin{remark}[Nonnegativity is essential]
Without $\alpha,\beta,\gamma\ge0$ rigidity fails: $(1,-1,0)$ has sum zero, hence invariant $\pi/\kappa$, yet the angles are not all zero. The hypothesis encodes the geometric fact (Theorem~\ref{thm:strictpos}) that interior angles are nonnegative, strictly positive at finite vertices.
\end{remark}

\subsection{Geometric degeneration}

\begin{definition}
For $t>0$ with $a+t<b-t$, the truncated area is $\mathcal{T}_{\kappa}(a,b;t)=\mathcal{A}_{\kappa}(a+t,b-t;h_{a,b})$.
\end{definition}

\begin{theorem}\label{thm:truncformula}
For $t>0$ with $a+t<b-t$,
$\displaystyle \mathcal{T}_{\kappa}(a,b;t) = \frac{F_{a,b}(b-t)-F_{a,b}(a+t)}{\kappa}$.
\end{theorem}
\begin{proof}
Slicing reduces to $\kappa^{-1}\int_{a+t}^{b-t}h_{a,b}^{-1}$, and on this compact subinterval of $(a,b)$ the ordinary fundamental theorem applies, the density being integrable by Theorem~\ref{thm:integrable}.
\end{proof}

\begin{theorem}[Strict subideality of truncations]
For $\kappa>0$ and $t>0$ with $a+t<b-t$: $\mathcal{T}_{\kappa}(a,b;t)<\pi/\kappa$.
\end{theorem}
\begin{proof}
$F_{a,b}(b-t)\le\pi/2$ always, while $F_{a,b}(a+t)>-\pi/2$ strictly, since $(2(a+t)-a-b)/(b-a)>-1$ exactly when $t>0$, and $\arcsin>-\pi/2$ on $(-1,1]$.
\end{proof}

\begin{theorem}[Degeneration]
For $a<b$: $\displaystyle\lim_{t\downarrow0}\mathcal{T}_{\kappa}(a,b;t)=\pi/\kappa$.
\end{theorem}
\begin{proof}
The right-hand side of Theorem~\ref{thm:truncformula} is a continuous function of $t$, with value $(F_{a,b}(b)-F_{a,b}(a))/\kappa=\pi/\kappa$ at $t=0$ by Lemma~\ref{lem:endpoints}; the formula is valid once $0<t<(b-a)/2$.
\end{proof}

\subsection{Angular degeneration}

\begin{theorem}[Maximising sequences degenerate]\label{thm:degen}
Let $\kappa>0$ and let $(\alpha_{n},\beta_{n},\gamma_{n})$ be admissible for every $n$. If $\mathcal{G}_{\kappa}(\alpha_{n},\beta_{n},\gamma_{n})\to\pi/\kappa$, then $\alpha_{n}\to0$, $\beta_{n}\to0$ and $\gamma_{n}\to0$.
\end{theorem}
\begin{proof}
Write $S_{n}=\alpha_{n}+\beta_{n}+\gamma_{n}=\pi-\kappa\,\mathcal{G}_{\kappa}(\alpha_{n},\beta_{n},\gamma_{n})$ identically; the right side converges to $\pi-\kappa(\pi/\kappa)=0$, so $S_{n}\to0$. Now $0\le\alpha_{n}\le S_{n}$ using $\beta_{n},\gamma_{n}\ge0$, and likewise for $\beta_{n}$ and $\gamma_{n}$; the squeeze theorem gives the three limits.
\end{proof}

Hence the ideal triangle is the unique limiting shape of an area-maximising sequence: rigidity holds asymptotically, not merely for exact maximisers.

\section{Isometries, and why one computation suffices}\label{sec:mobius}

\begin{definition}
For $A,B,C,D\in\RR$ the associated real M\"obius map is $T(z)=(Az+B)/(Cz+D)$, with determinant $\det T = AD-BC$. On the boundary line it restricts to $x\mapsto(Ax+B)/(Cx+D)$, with pole at $x=-D/C$, sent to $\infty$.
\end{definition}

\begin{theorem}[Imaginary part]\label{thm:im}
For all $A,B,C,D\in\RR$ and all $z$ with $Cz+D\ne0$,
\[
\Imm T(z) = \frac{(AD-BC)\,\Imm z}{|Cz+D|^{2}} .
\]
\end{theorem}
\begin{proof}[Proof sketch]
Multiply numerator and denominator by $\overline{Cz+D}$ and take imaginary parts; the real coefficients make the cross terms combine to $(AD-BC)\Imm z$, and the denominator becomes $|Cz+D|^{2}$.
\end{proof}

\begin{theorem}[Invariance of the upper half-plane]
If $AD-BC>0$ and $\Imm z>0$, then $Cz+D\ne0$ and $\Imm T(z)>0$.
\end{theorem}
\begin{proof}
If $Cz+D=0$, its imaginary part $C\Imm z$ vanishes, forcing $C=0$ since $\Imm z>0$; then its real part $D$ vanishes too. But $C=D=0$ makes $AD-BC=0$, contradicting positivity. Theorem~\ref{thm:im} then exhibits $\Imm T(z)$ as a quotient of positive quantities.
\end{proof}

\begin{theorem}[Derivative]\label{thm:mobderiv}
If $Cz+D\ne0$ then $T$ is complex-differentiable at $z$ with $T'(z)=(AD-BC)/(Cz+D)^{2}$.
\end{theorem}
\begin{proof}
Quotient rule: $\bigl(A(Cz+D)-C(Az+B)\bigr)/(Cz+D)^{2}=(AD-BC)/(Cz+D)^{2}$.
\end{proof}

\begin{theorem}[Pointwise conformality: the isometry identity]\label{thm:isometry}
If $\det T>0$ and $\Imm z>0$, then
\[
\frac{|T'(z)|}{\Imm T(z)} = \frac{1}{\Imm z}.
\]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:mobderiv} and positivity, $|T'(z)|=(AD-BC)/|Cz+D|^{2}$; by Theorem~\ref{thm:im}, $\Imm T(z)=(AD-BC)\Imm z/|Cz+D|^{2}$. Dividing, the common factor cancels.
\end{proof}

\begin{corollary}[Real M\"obius maps are hyperbolic isometries]
The hyperbolic line element is $ds=|dz|/(\sqrt{\kappa}\,y)$. Under $T$, $|dz|$ is multiplied by $|T'(z)|$ while $y=\Imm z$ becomes $\Imm T(z)$. Theorem~\ref{thm:isometry} says the ratio is unchanged, so $T$ preserves hyperbolic length pointwise, hence distance, area, and (being conformal) angles.
\end{corollary}

\subsection{Sharp three-transitivity}

\begin{definition}[Cross-ratio normaliser]
For $p<q<r$ let $T_{p,q,r}$ be the real M\"obius map with coefficients $(A,B,C,D)=\bigl(q-r,\,-p(q-r),\,q-p,\,-r(q-p)\bigr)$, that is
\[
T_{p,q,r}(x)=\frac{(q-r)(x-p)}{(q-p)(x-r)} .
\]
\end{definition}

\begin{theorem}[Orientation]\label{thm:detpos}
$\det T_{p,q,r} = (r-q)(q-p)(r-p)>0$ for $p<q<r$.
\end{theorem}
\begin{proof}
$AD-BC = (q-r)\bigl(-r(q-p)\bigr)+p(q-r)(q-p) = (q-r)(q-p)(p-r) = (r-q)(q-p)(r-p)$, a product of three positive numbers.
\end{proof}

\begin{theorem}[Normalisation]\label{thm:normalise}
For $p<q<r$: $T_{p,q,r}(p)=0$, $T_{p,q,r}(q)=1$, and $Cr+D=(q-p)r-r(q-p)=0$, so $r$ is the pole and $T_{p,q,r}(r)=\infty$.
\end{theorem}
\begin{proof}
At $x=p$ the numerator vanishes and the denominator $(q-p)(p-r)$ does not. At $x=q$ numerator and denominator are both $(q-r)(q-p)\ne0$. The pole identity is immediate.
\end{proof}

\begin{theorem}[Uniqueness]\label{thm:unique}
A real M\"obius map fixing $0$, $1$ and $\infty$ is the identity on the boundary line: if $C=0$ (no finite pole, i.e.\ $\infty$ fixed), $D\ne0$, and $x\mapsto(Ax+B)/D$ fixes $0$ and $1$, then $(Ax+B)/D=x$ for all $x$.
\end{theorem}
\begin{proof}
Fixing $0$ gives $B/D=0$, so $B=0$; fixing $1$ then gives $A/D=1$, so $A=D$; hence the map is $x\mapsto Dx/D=x$.
\end{proof}

\begin{corollary}[Sharp three-transitivity]
For $p<q<r$ the normalising map is unique: any two real M\"obius maps carrying $(p,q,r)$ to $(0,1,\infty)$ agree on the whole boundary line. Consequently three distinct boundary points determine an ideal triangle, uniquely up to a unique hyperbolic isometry.
\end{corollary}

\begin{corollary}[Universality of the area]
Every ideal triangle in $\HH$ is the image under a hyperbolic isometry of the standard ideal triangle with vertices $0$, $1$, $\infty$, and therefore has area $\pi/\kappa$; in particular $\mathcal{A}_{\kappa}(0,1;h_{0,1})=\pi/\kappa$ is the universal value. (This uses the integrated M\"obius invariance of hyperbolic area, Conjecture~\ref{conj:B}, whose infinitesimal form is Theorem~\ref{thm:isometry}.)
\end{corollary}

\section{Variable curvature: comparison and pinching}\label{sec:curvature}

\begin{definition}
$\displaystyle \mathcal{A}^{K}(a,b;\mathrm{low}) = \int_{a}^{b}\!\left(\int_{\mathrm{low}(x)}^{\infty}\frac{dy}{K(x)y^{2}}\right)dx$, the area for the curvature profile $-K$.
\end{definition}

\begin{theorem}[Variable slicing]\label{thm:varslice}
If $a<b$ and $\mathrm{low}>0$ on $(a,b)$, then
$\displaystyle \mathcal{A}^{K}(a,b;\mathrm{low}) = \int_{a}^{b}\frac{dx}{K(x)\mathrm{low}(x)}$.
No positivity, continuity or measurability hypothesis on $K$ is needed beyond what makes the outer integral meaningful.
\end{theorem}

\begin{lemma}[Reference integral]\label{lem:ref}
For $a<b$ and $\kappa\ne0$: $\int_{a}^{b}\kappa^{-1}h_{a,b}(x)^{-1}dx=\pi/\kappa$.
\end{lemma}

\begin{theorem}[Upper comparison]\label{thm:upper}
Let $a<b$, $\kappa_{1}>0$, and $K$ continuous on $[a,b]$ with $K\ge\kappa_{1}$ there. Then $\mathcal{A}^{K}(a,b;h_{a,b})\le\pi/\kappa_{1}$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:varslice} the area is $\int_{a}^{b}K^{-1}h_{a,b}^{-1}$. Both this and the reference integrand $\kappa_{1}^{-1}h_{a,b}^{-1}$ are integrable: the chordal density is integrable by Theorem~\ref{thm:integrable} and $K^{-1}$ is continuous, hence bounded, on the compact interval ($K\ge\kappa_{1}>0$ never vanishes). Pointwise $K(x)^{-1}\le\kappa_{1}^{-1}$ and $h_{a,b}^{-1}\ge0$, so the integrands are ordered; monotonicity of the integral and Lemma~\ref{lem:ref} finish.
\end{proof}

\begin{theorem}[Lower comparison]
Let $a<b$, $\kappa_{2}>0$, and $K$ continuous and positive on $[a,b]$ with $K\le\kappa_{2}$. Then $\pi/\kappa_{2}\le\mathcal{A}^{K}(a,b;h_{a,b})$.
\end{theorem}

\begin{theorem}[Pinching]
If $a<b$ and $0<\kappa_{1}\le K\le\kappa_{2}$ on $[a,b]$ with $K$ continuous, then
\[
\frac{\pi}{\kappa_{2}} \le \mathcal{A}^{K}\bigl(a,b;h_{a,b}\bigr) \le \frac{\pi}{\kappa_{1}} .
\]
\end{theorem}
\begin{proof}
$\kappa_{2}\ge K(a)\ge\kappa_{1}>0$, so both comparison theorems apply.
\end{proof}

\begin{theorem}[Sharpness]
For constant $K\equiv\kappa$, $\mathcal{A}^{\kappa}(a,b;h_{a,b})=\pi/\kappa=\mathcal{A}_{\kappa}(a,b;h_{a,b})$. Hence neither pinching inequality can be improved.
\end{theorem}

\begin{interpretation}
Curvature magnitude and ideal area are in exact inverse proportion, $\Area\cdot\kappa=\pi$. More negative curvature compresses the plane and shrinks the largest triangle; the flat limit $\kappa\downarrow0$ sends $\pi/\kappa\to\infty$, recovering the Euclidean absence of a maximum. This is the elementary prototype of Riemannian comparison geometry --- Rauch, Toponogov, Bishop--Gromov --- in which curvature bounds are converted into metric and volume bounds.
\end{interpretation}

\section{Algorithms and numerics}\label{sec:algorithms}

\begin{algorithm}[Exact area of an ideal polygon]
Input: $\kappa>0$ and increasing finite boundary vertices $v_{0}<\dots<v_{m}$, with an implicit vertex at $\infty$. Output: $m\pi/\kappa$. Complexity: $O(m)$ validation, $O(1)$ arithmetic. Remarkably, no vertex position enters the answer (Theorem~\ref{thm:polygon}).
\end{algorithm}

\begin{remark}[Quadrature]
The integral $\int_{a}^{b}h_{a,b}^{-1}$ has inverse-square-root singularities at both endpoints, so naive uniform quadrature converges at rate $O(N^{-1/2})$. The correct method removes the singularity by the substitution $x=\frac{a+b}{2}+\frac{b-a}{2}\sin\psi$, $\psi\in[-\pi/2,\pi/2]$, under which $dx=\frac{b-a}{2}\cos\psi\,d\psi$ and $h_{a,b}(x)=\frac{b-a}{2}\cos\psi$, so that the integrand becomes the constant $1$ and the integral is the length $\pi$ of the $\psi$-interval --- exactly. This is also the cleanest proof of Theorem~\ref{thm:pi}. For an independent check, tanh--sinh (double-exponential) quadrature handles endpoint algebraic singularities with essentially exponential convergence.
\end{remark}

\begin{remark}[Truncation error]
From Theorem~\ref{thm:truncformula} and $\arccos(1-\varepsilon)\sim\sqrt{2\varepsilon}$,
\[
\frac{\pi}{\kappa}-\mathcal{T}_{\kappa}(a,b;t) \sim \frac{4}{\kappa}\sqrt{\frac{t}{b-a}} \qquad (t\downarrow0),
\]
the square-root rate being a direct signature of the endpoint singularity.
\end{remark}

\begin{algorithm}[Normalising a boundary triple]
Input $p<q<r$. Set $A=q-r$, $B=-p(q-r)$, $C=q-p$, $D=-r(q-p)$, $\det=(r-q)(q-p)(r-p)$. Output $(A,B,C,D,\det)$. Complexity $O(1)$; correctness is Theorems~\ref{thm:detpos}--\ref{thm:normalise}, uniqueness Theorem~\ref{thm:unique}.
\end{algorithm}

\begin{remark}[Sample numerics]
At $\kappa=1$ every ideal triangle has area $\pi\approx3.14159265$; the ideal quadrilateral $2\pi\approx6.28318531$; the ideal hexagon $4\pi\approx12.56637$. At $\kappa=2$ the ideal triangle has area $\pi/2\approx1.5708$. In the family of Section~\ref{sec:angles} with $\kappa=1$, $\theta=2\pi/3$, $\varphi=\pi/3$: angles $\pi/3,\pi/3,0$ and area $\pi/3\approx1.0472$, matching $(\pi-\pi/3-\pi/3)/1$. Truncating at $t=10^{-3}$ with $a=0$, $b=1$, $\kappa=1$ gives $2\arcsin(1-2\cdot10^{-3})\approx3.0151$, below $\pi$ by about $0.1265$, consistent with $4\sqrt{t}=0.1265$.
\end{remark}

\section{Applications and context}

\textbf{Quantisation of hyperbolic surface area.} A closed orientable surface of genus $g\ge2$ carrying a hyperbolic metric of curvature $-1$ has total area exactly $2\pi|\chi|=4\pi(g-1)$, determined by topology alone. No deformation changes it; the bounded-area theorem for triangles is the local statement of which this is the global integral.

\textbf{Thin triangles and coarse geometry.} Bounded area forces bounded thickness: every geodesic triangle in $\HH$ is $\delta$-thin for a universal $\delta$. Abstracting this property from any metric model gives Gromov's notion of a hyperbolic group, with solvable word problems and linear isoperimetric inequalities as consequences.

\textbf{Ideal triangulations and knot invariants.} The three-dimensional analogue of the ideal triangle is the ideal tetrahedron; hyperbolic structures on knot complements are constructed by gluing finitely many and solving the gluing equations. Finiteness of ideal volume --- the analogue of our $\pi/\kappa$ --- makes hyperbolic volume a real-valued knot invariant, and the formula $(n-2)\pi/\kappa$ is the two-dimensional model for additivity of ideal volume under decomposition.

\textbf{Modular geometry.} The standard fundamental domain of $\mathrm{PSL}(2,\mathbb{Z})$ acting on $\HH$ is a hyperbolic triangle with one ideal vertex at $\infty$ and angles $\pi/3,\pi/3,0$, of area $\pi-2\pi/3=\pi/3$ --- an instance of Theorem~\ref{thm:gb}. This number pervades the theory of modular forms.

\textbf{Tilings and visual art.} Escher's \emph{Circle Limit} woodcuts tile the hyperbolic plane by congruent figures; the tiles do not shrink hyperbolically, the apparent shrinkage being an artefact of Euclidean rendering. Ideal triangulations by copies of \emph{the} ideal triangle --- all congruent --- are the cleanest example: infinitely many pieces, each of area exactly $\pi$.

\section{Discussion and future directions}\label{sec:discussion}

\subsection{Scope}
Two deliberate restrictions remain. First, the derived Gauss--Bonnet theorem of Section~\ref{sec:angles} covers triangles with \emph{at least one ideal vertex} --- a family including the ideal triangle, the modular triangle, and every degeneration between --- but not yet triangles with three finite vertices. Second, universality of the area uses the integrated M\"obius invariance of hyperbolic area, of which Theorem~\ref{thm:isometry} is the infinitesimal form. Both are addressed below.

\begin{conjecture}[Full Gauss--Bonnet, all vertices finite]\label{conj:A}
For any three points of the upper half-plane not on a common geodesic, the region bounded by the three connecting geodesics has hyperbolic area $(\pi-(\alpha+\beta+\gamma))/\kappa$, where $\alpha,\beta,\gamma$ are the angles between the tangent vectors of the sides at the three vertices.
\end{conjecture}

\emph{Why the one-ideal-vertex case should already be the whole theorem.} Extend one side of an arbitrary finite triangle to the boundary; the triangle becomes the difference of two triangles each having an ideal vertex at $\infty$, for which Section~\ref{sec:angles} gives the area. The identity then follows by additivity of the slicing integral together with a single angle-addition identity at the shared vertex --- no new analysis, only bookkeeping of which region is added and which subtracted. The three previously missing ingredients are now in place: the exact antiderivative $F_{a,b}$, integrability across the singular endpoints, and a conformally invariant notion of interior angle. \emph{Falsifiable form:} compute the area of the triangle with vertices $i$, $2i$, $1+i$ numerically; the conjecture is refuted if it differs from $\pi-\alpha-\beta-\gamma$ for the numerically computed angles.

\begin{conjecture}[M\"obius invariance of area]\label{conj:B}
For $T$ a real M\"obius map of positive determinant and $S$ a measurable subset of the upper half-plane,
\[
\int_{T(S)}\frac{dx\,dy}{y^{2}} = \int_{S}\frac{dx\,dy}{y^{2}} .
\]
\end{conjecture}

This is the integrated form of Theorem~\ref{thm:isometry}: the real Jacobian determinant of $T$ equals $|T'(z)|^{2}$ by holomorphy, while the density transforms by $\Imm T(z)^{-2}=|T'(z)|^{-2}\Imm(z)^{-2}$, and the factors cancel.

\subsection{Further directions}
\begin{enumerate}
\item \textbf{A second model.} Develop the Poincar\'e disk model and the Cayley transform $z\mapsto(z-i)/(z+i)$, and check that ideal triangle area is model-independent.
\item \textbf{Ideal polygons with all vertices finite on $\RR$.} Prove $(n-2)\pi/\kappa$ without the convenient vertex at $\infty$, using Conjecture~\ref{conj:B} to move one vertex there.
\item \textbf{Finite triangles converging to an ideal one.} Construct an explicit sequence of triangles with three finite vertices whose vertices converge to three boundary points, each angle tending to zero and area to $\pi/\kappa$.
\item \textbf{Two-dimensional variable curvature.} Allow $K=K(x,y)$ and relate the area functional to the intrinsic curvature $-e^{-2u}\Delta u$ of the conformal metric $e^{2u}(dx^{2}+dy^{2})$; comparison should follow from the maximum principle for the Liouville equation.
\item \textbf{Holonomy.} Express the angular defect as rotational holonomy of the Levi-Civita connection around the triangle, and prove that ideal maximality is invariant under all hyperbolic isometries.
\item \textbf{Higher dimensions.} The ideal tetrahedron in $\mathbb{H}^{3}$ has volume given by the Lobachevsky function, maximised by the regular ideal tetrahedron at $3\Lambda(\pi/3)\approx1.0149$; the planar story here is the degenerate case with a closed-form maximum.
\item \textbf{Quantitative stability.} Theorem~\ref{thm:degen} says near-maximal area forces near-zero angles. Make this geometric: if the area is within $\varepsilon$ of maximal, how close must the triangle be to an ideal one in Hausdorff distance on the compactified plane?
\end{enumerate}

\subsection{The shape of the argument}
One improper integral, $\int_{a}^{b}dx/\sqrt{(x-a)(b-x)}=\pi$, supplies the area of the ideal triangle and, by its independence of $a$ and $b$, the congruence of all such triangles. One algebraic identity, $\Area=(\pi-\alpha-\beta-\gamma)/\kappa$, supplies maximality, rigidity, and the polygon formula. One conformality identity, $|T'|/\Imm T = 1/\Imm$, supplies the isometry group and, through three-transitivity, the reduction of the general ideal triangle to the normal form $(0,1,\infty)$. Three inputs; the rest is bookkeeping.

\bigskip
\noindent\textbf{Classical background.} The angle-defect formula for hyperbolic triangles is due to Lambert and Gauss; the half-plane model to Beltrami and Poincar\'e; the classification of geodesics and the action of $\mathrm{PSL}(2,\RR)$ is standard nineteenth-century material. Thurston's ideal-tetrahedron programme and Gromov's $\delta$-hyperbolicity are the two modern developments most directly downstream.

